      "type": "parameter-extractor",
      "param": {
        "query": ["attention", "1"],
        "parameters": [
          ["Review checkpoints", "checkpoints", "array[string]"]
        ],
        "instruction": "Extract specific contract review checkpoints from the user's concerns"
      }
    },
    {
      "id": "3",
      "type": "code",
      "param": {
        "variables": [
          ["checkpoints", ["checkpoints", "2"]],
          ["workfield", ["workfield", "1"]]
        ],
        "outputs": [["industry_checkpoints", "array[string]"]],
        "code": "def main(checkpoints: list, workfield: str):\n\tindustry_specific = []\n\tif workfield == 'construction':\n\t\tindustry_specific = ['payment terms', 'liability clauses', 'dispute resolution']\n\telif workfield == 'technology':\n\t\tindustry_specific = ['IP ownership', 'data protection', 'termination clauses']\n\treturn {\n\t\t\"industry_checkpoints\": checkpoints + industry_specific\n\t}"
      }
    },
    {
      "id": "4",
      "type": "document-extractor",
      "param": {
        "variable_selector": ["contract", "1"]
      }
    },
    {
      "id": "5",
      "type": "llm",
      "param": {
        "system": "You are a contract risk reviewer. Analyze the contract text against the checkpoints and industry factors, prioritize risks from the perspective of {{#'1'.apart#}}",
        "user": "Analyze the contract text {{#'4'.text#}} against these checkpoints: {{#'3'.industry_checkpoints#}}. Provide risk analysis and improvement suggestions."
      }
    },
    {
      "id": "6",
      "type": "template-transform",
      "param": {
        "variables": [
          ["analysis", ["text", "5"]],
          ["checkpoints", ["industry_checkpoints", "3"]]
        ],
        "template": "Contract Risk Review Report\n\nReview Checkpoints: {{checkpoints}}\n\nAnalysis Results:\n{{analysis}}\n\nImprovement Suggestions:\n1. {{analysis.split('.')[0]}}\n2. {{analysis.split('.')[1]}}\n3. {{analysis.split('.')[2]}}"
      }
    },
    {
      "id": "7",
      "type": "end",
      "param": {
        "outputs": [["result", ["output", "6"]]]
      }
    }
  ],
